#!/usr/bin/env node
/**
 * build-agent-bundle — the agent files the PLUGIN registers, with their shared
 * fragments inlined.
 *
 * Every agent reaches a session twice: under the plugin's namespace
 * (`great-cto:senior-dev`) and as the copy SessionStart installs into
 * `~/.claude/agents` (`senior-dev`). Since 2026-09-21 the installed copy carries the
 * `agents/_shared/` fragments its pointers name, because that relative path does not
 * exist in a user's project. The plugin copy still carried the pointers, so the 4% of
 * dispatches that use the prefixed name got an agent without half of its contract.
 *
 * ADR-027 measured the alternative — dropping the plugin registration — and refused
 * it: an agent installed during SessionStart is not available until the NEXT session,
 * so a user's first session would have none. Both registrations therefore carry the
 * same text, and this generates the plugin's half.
 *
 * `agents/` stays the source: one file per agent, pointers intact, what a human edits.
 * `agents-full/` is build output that is committed, because a plugin install is a
 * copy of the repository with no build step.
 *
 * Usage:
 *   node scripts/build-agent-bundle.mjs           # write agents-full/
 *   node scripts/build-agent-bundle.mjs --check   # exit 1 if it is stale
 */
import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expandSharedRefs } from './lib/shared-fragments.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC = join(ROOT, 'agents');
const OUT = join(ROOT, 'agents-full');
export const HEADER = '<!-- generated by scripts/build-agent-bundle.mjs from agents/ — edit the source, not this -->';

/**
 * The plugin copy's description: the source's first sentence, at most 90 characters.
 *
 * ADR-027 option E. Every agent is listed twice in a session — `senior-dev` (the
 * installed copy, 96% of dispatches) and `great-cto:senior-dev` (this one) — and each
 * listing carries the description: ~4.8k tokens of repeated text per session. The
 * installed copy keeps the full description the model routes by; this one keeps one
 * line, enough for a user's first session, when only the plugin copy exists.
 */
export function shortDescription(desc) {
  let d = String(desc).trim().replace(/^"(.*)"$/, '$1').replace(/\\"/g, '"');
  // Sentences until the line says what the agent does: "Use after QA passes." alone
  // does not, so a first sentence under 40 characters takes the next one too.
  const sentences = d.match(/[^.!?]+[.!?]+(\s|$)|[^.!?]+$/g) || [d];
  let out = '';
  for (const sentence of sentences) {
    out += sentence;
    if (out.trim().length >= 40) break;
  }
  d = out.trim();
  if (d.length > 90) d = `${d.slice(0, 89).replace(/\s+\S*$/, '')}…`;
  return JSON.stringify(d);
}

/** agent name → the text the plugin should register. */
export function bundle({ src = SRC } = {}) {
  const out = new Map();
  for (const f of readdirSync(src).filter((n) => n.endsWith('.md') && !n.startsWith('_')).sort()) {
    const raw = readFileSync(join(src, f), 'utf8');
    // Only the body's pointers are inlined.
    const m = raw.match(/^(---\n[\s\S]*?\n---\n)([\s\S]*)$/);
    // The frontmatter is the agent's identity (name, tools, model) and is left alone,
    // except the description, which the plugin copy lists in one line (ADR-027 E).
    const front = (m ? m[1] : '').replace(/^description:\s*(.*)$/m, (_, d) => `description: ${shortDescription(d)}`);
    const body = m ? m[2] : raw;
    const { text } = expandSharedRefs(body, { root: src });
    out.set(f, `${front}${HEADER}\n${text.endsWith('\n') ? text : `${text}\n`}`);
  }
  return out;
}

function main() {
  const check = process.argv.includes('--check');
  const built = bundle();
  if (check) {
    const have = existsSync(OUT) ? readdirSync(OUT).filter((f) => f.endsWith('.md')).sort() : [];
    const want = [...built.keys()];
    const stale = have.join(',') !== want.join(',')
      || want.some((f) => readFileSync(join(OUT, f), 'utf8') !== built.get(f));
    if (stale) {
      process.stdout.write('stale: agents-full/ — run: node scripts/build-agent-bundle.mjs\n');
      process.exit(1);
    }
    process.stdout.write(`agents-full: ${want.length} agent(s), up to date\n`);
    process.exit(0);
  }
  rmSync(OUT, { recursive: true, force: true });
  mkdirSync(OUT, { recursive: true });
  for (const [f, text] of built) writeFileSync(join(OUT, f), text);
  process.stdout.write(`agents-full: wrote ${built.size} agent(s) with their shared fragments inlined\n`);
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) main();
